import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNotSame;

public class GJChronology_getInstance_TriageGen1Test {

    @Test
    public void testGetInstance_NullCutover_UTC() {
        // Tests the branch where gregorianCutover is null and zone is UTC
        // This covers: zone = DateTimeUtils.getZone(zone), cutoverInstant = DEFAULT_CUTOVER, 
        // chronos == null, zone == DateTimeZone.UTC
        GJChronology chrono = GJChronology.getInstance(DateTimeZone.UTC, null, 4);

        assertNotNull(chrono);
        assertEquals(DateTimeZone.UTC, chrono.getZone());
        assertEquals(4, chrono.getMinimumDaysInFirstWeek());
    }

    @Test
    public void testGetInstance_WithCutover_NonUTC() {
        // Tests the branch where gregorianCutover is not null and zone is not UTC
        // This covers: cutoverInstant = gregorianCutover.toInstant(), chronos == null, zone != UTC
        DateTimeZone zone = DateTimeZone.forID("Asia/Shanghai");
        Instant cutover = new Instant(1234567890L);
        int minDays = 5;

        GJChronology chrono = GJChronology.getInstance(zone, cutover, minDays);

        assertNotNull(chrono);
        assertEquals(zone, chrono.getZone());
        assertEquals(cutover, chrono.getGregorianCutover());
        assertEquals(minDays, chrono.getMinimumDaysInFirstWeek());
    }

    @Test
    public void testGetInstance_CacheHit() {
        // Tests the branch where the chronology is already in the cache
        // This covers: chronos != null, the loop finding the matching chrono
        DateTimeZone zone = DateTimeZone.forID("Europe/London");
        Instant cutover = new Instant(2000, 1, 1, 0, 0, 0, 0);
        int minDays = 4;

        // First call to populate cache
        GJChronology firstCall = GJChronology.getInstance(zone, cutover, minDays);

        // Second call should return the same instance from cache
        GJChronology secondCall = GJChronology.getInstance(zone, cutover, minDays);

        assertNotNull(secondCall);
        assertEquals(firstCall, secondCall);
        // Identity check to ensure it truly came from the cache
        assertEquals(firstCall.hashCode(), secondCall.hashCode());
    }

    @Test
    public void testGetInstance_CacheMiss_DifferentParams() {
        // Tests the branch where the cache exists but the specific parameters don't match
        // This covers: chronos != null, loop completes without return, adding new chrono to cache
        DateTimeZone zone = DateTimeZone.UTC;
        int minDays1 = 4;
        int minDays2 = 5;

        GJChronology chrono1 = GJChronology.getInstance(zone, null, minDays1);
        GJChronology chrono2 = GJChronology.getInstance(zone, null, minDays2);

        assertNotNull(chrono1);
        assertNotNull(chrono2);
        assertNotSame(chrono1, chrono2);
        assertEquals(minDays1, chrono1.getMinimumDaysInFirstWeek());
        assertEquals(minDays2, chrono2.getMinimumDaysInFirstWeek());
    }

    @Test
    public void testGetInstance_CacheMiss_DifferentCutover() {
        // Tests the branch where the cache exists but the cutover instant is different
        DateTimeZone zone = DateTimeZone.forID("America/New_York");
        int minDays = 4;
        Instant cutover1 = new Instant(1000L);
        Instant cutover2 = new Instant(2000L);

        GJChronology chrono1 = GJChronology.getInstance(zone, cutover1, minDays);
        GJChronology chrono2 = GJChronology.getInstance(zone, cutover2, minDays);

        assertNotNull(chrono1);
        assertNotNull(chrono2);
        assertNotSame(chrono1, chrono2);
        assertEquals(cutover1, chrono1.getGregorianCutover());
        assertEquals(cutover2, chrono2.getGregorianCutover());
    }

    @Test
    public void testGetInstance_WithReadableInstantImplementation() {
        // Tests the branch specifically using a ReadableInstant implementation that isn't Instant
        // to ensure toInstant() is called correctly.
        DateTimeZone zone = DateTimeZone.UTC;
        ReadableInstant ri = new ReadableInstant() {
            @Override
            public long getMillis() {
                return 5000L;
            }
            @Override
            public Instant toInstant() {
                return new Instant(5000L);
            }
        };

        GJChronology chrono = GJChronology.getInstance(zone, ri, 4);
        assertEquals(new Instant(5000L), chrono.getGregorianCutover());
    }
}
